import re
import sys

sys.stdout.reconfigure(encoding="utf-8")

MAIN = ["main.tex", "part_abstract.tex", "part_body1.tex", "part_body2.tex",
        "part_body3.tex", "part_body4.tex", "part_appendix.tex"]
PEND = ["_t1_q2.tex", "_t2_q2.tex", "_t3_q2.tex", "_t1_q3.tex", "_t2_q3.tex",
        "_t3_q3.tex", "_q1tables.tex"]
RL = re.compile(r"\\label\{([^}]+)\}")
RR = re.compile(r"\\(?:ref|eqref|autoref)\{([^}]+)\}")

labs, refs = {}, {}
for f in MAIN:
    t = open(f, encoding="utf-8").read()
    for m in RL.findall(t):
        labs.setdefault(m, []).append(f)
    for m in RR.findall(t):
        refs.setdefault(m, []).append(f)
pend = {}
for f in PEND:
    for m in RL.findall(open(f, encoding="utf-8").read()):
        pend[m] = f

print("悬空 ref（正文无 label）:")
for r, fs in refs.items():
    if r not in labs:
        tag = f"  [在 {pend[r]} 待插入]" if r in pend else "  [完全缺失]"
