print("重复 label:")
for l, fs in labs.items():
    if len(fs) > 1:
        print(f"   {l} {fs}")
print("未被引用的 label:")
for l, fs in labs.items():
    if l not in refs and not l.startswith("eq:"):
        print(f"   {l} {fs}")

