"""统计各节加粗密度：加粗字符数 / 正文字符数，找出重灾区。"""
import re
import sys

sys.stdout.reconfigure(encoding="utf-8")

MACROS = ["corestatement", "methodname", "keyfinding", "keypoint",
          "keyresult", "innovation"]
BODY = ["part_body1.tex", "part_body2.tex", "part_body3.tex", "part_body4.tex"]


def brace_span(s: str, i: int) -> int:
    """i 指向 '{'，返回匹配的 '}' 下标。"""
    d = 0
    while i < len(s):
        if s[i] == "{":
            d += 1
        elif s[i] == "}":
            d -= 1
            if d == 0:
                return i
        i += 1
    return len(s) - 1


def cjk(s: str) -> int:
    """中日韩字符数，排除 LaTeX 命令与数字的干扰。"""
    return len(re.findall(r"[\u4e00-\u9fff]", s))


for f in BODY:
    t = open(f, encoding="utf-8").read()
    # 按 subsubsection 切块
    parts = re.split(r"\\subsubsection\{([^}]*)\}", t)
    blocks = [("（节前引言）", parts[0])]
    for i in range(1, len(parts), 2):
        blocks.append((parts[i], parts[i + 1]))
    print(f"\n{'='*78}\n{f}\n{'='*78}")
    for name, body in blocks:
        tot = cjk(body)
        if tot < 30:
            continue
        bold = 0
        counts = {}
        for m in MACROS:
            for mo in re.finditer(r"\\" + m + r"\{", body):
                s = mo.end() - 1
                e = brace_span(body, s)
                bold += cjk(body[s:e])
                counts[m] = counts.get(m, 0) + 1
        pct = 100 * bold / tot
        flag = "  ⚠⚠" if pct > 35 else ("  ⚠" if pct > 25 else "")
        det = " ".join(f"{k[:4]}{v}" for k, v in sorted(counts.items()))
        print(f"  {pct:5.1f}%  {bold:>4}/{tot:<5} {name[:30]:<32}{det}{flag}")

